/**
 * Every district in Türkiye, grouped by the province it is in.
 *
 * Generated, not written. OCHA COD-AB-TUR (CC BY-IGO), simplified and projected
 * once at build time:
 *
 *   unzip -o tur.zip tur_admin2.geojson
 *   # carry adm2_pcode through as "pcode"
 *   npx mapshaper@0.6 districts.geojson  *     -proj "+proj=lcc +lat_1=37 +lat_2=41 +lon_0=35 +lat_0=39"  *     -simplify interval=900 keep-shapes  *     -o format=svg id-field=pcode width=1800 districts.svg
 *
 * Simplified by ground interval rather than by a percentage: a percentage keeps
 * the same share of each shape's own vertices, so a small district ends up
 * smoother than a large one for no reason. 900 metres is finer than a pixel at
 * the size any province is drawn here.
 *
 * Every province is projected in one national system, so `viewBox` is the zoom:
 * each entry carries the box that frames its own districts, and switching
 * provinces is switching that string. No second projection, no arithmetic in
 * the page.
 *
 * ## The names, and why they are derived rather than typed
 *
 * The source ships an ASCII field ("Cigli") and a Turkish one that has been
 * through a locale-broken case conversion:
 *
 *   Çi̇ğli̇      i followed by U+0307 COMBINING DOT ABOVE
 *   Karşiyaka  where the record writes Karşıyaka
 *
 * That looks like lost information and is not. The conversion was consistent:
 * a dotted i survived as "i + U+0307" and a dotless ı as a bare "i". So the
 * repair is exact — bare i becomes ı, i+U+0307 becomes i — and it was checked
 * against the thirty İzmir districts and eighty-one provinces written out by
 * hand before this file replaced them. Thirty of thirty and seventy-nine of
 * eighty-one.
 *
 * The two that disagreed are worth naming, because they say what this repair
 * cannot do:
 *
 *   Eskişehir  the source itself is wrong — the last i lost its dot before the
 *              case conversion, so the rule turns it into "Eskişehır". Corrected
 *              by hand above; a source typo is not something a rule can find.
 *   Hakkari    the source spells it without the circumflex. That is a live
 *              disagreement in Turkish usage rather than an error, and the
 *              source's spelling is kept.
 *
 * So: mostly right, and not provably right everywhere. A district whose name
 * does not match the record counts nothing and looks exactly like a district
 * nobody has researched — which is why the page says out loud when a reading
 * matches no shape, rather than leaving it to be noticed.
 */
import type { PlaceShape } from './shape.js';

export interface ProvinceDistricts {
  /** As written in Turkish. What the record is matched against. */
  province: string;
  /** The box that frames this province's districts, in the national projection. */
  viewBox: string;
  districts: PlaceShape[];
}

/** The whole country, for reference: every viewBox above is a window onto this. */
export const DISTRICTS_VIEWBOX = '0 0 1800 786';

